function [y] = decimal_year(j)
%DECIMAL_YEAR  The decimal year of a Julian date: its year plus the fraction of that year gone.
%   j: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    u = asils.models.caltime.utc_of_jd(j);
    j0 = asils.models.caltime.jd_utc([u(1); 1; 1; 0; 0; 0]);
    j1 = asils.models.caltime.jd_utc([(u(1) + 1); 1; 1; 0; 0; 0]);
    y = (u(1) + ((j - j0) / (j1 - j0)));
end
